import [IO] from "std/io.bpl";

# Builder pattern for complex object construction
struct HttpRequest {
    method: string,
    url: string,
    headers: string,
    body: string,
    timeout: int,
}

struct HttpRequestBuilder {
    method: string,
    url: string,
    headers: string,
    body: string,
    timeout: int,

    frame new() ret HttpRequestBuilder {
        return HttpRequestBuilder {
            method: "GET",
            url: "",
            headers: "",
            body: "",
            timeout: 30
        };
    }

    frame setMethod(this: *HttpRequestBuilder, m: string) ret *HttpRequestBuilder {
        this.method = m;
        return this;
    }

    frame setUrl(this: *HttpRequestBuilder, u: string) ret *HttpRequestBuilder {
        this.url = u;
        return this;
    }

    frame setBody(this: *HttpRequestBuilder, b: string) ret *HttpRequestBuilder {
        this.body = b;
        return this;
    }

    frame setTimeout(this: *HttpRequestBuilder, t: int) ret *HttpRequestBuilder {
        this.timeout = t;
        return this;
    }

    frame build(this: *HttpRequestBuilder) ret HttpRequest {
        return HttpRequest {
            method: this.method,
            url: this.url,
            headers: this.headers,
            body: this.body,
            timeout: this.timeout
        };
    }
}

frame main() ret int {
    # Fluent builder pattern
    local builder: HttpRequestBuilder = HttpRequestBuilder.new();
    local request: HttpRequest = builder
        .setMethod("POST")
        .setUrl("https://api.example.com/data")
        .setBody("{\"key\": \"value\"}")
        .setTimeout(60)
        .build();

    IO.print("Request built:\n");
    IO.print("  Method: ");
    IO.print(request.method);
    IO.print("\n  URL: ");
    IO.print(request.url);
    IO.print("\n  Body: ");
    IO.print(request.body);
    IO.print("\n  Timeout: ");
    IO.printInt(request.timeout);
    IO.print("s\n");

    return 0;
}

import [IO] from "std/io.bpl";

# Maybe<T> represents a value that might not exist
enum Maybe<T> {
    Some(T),
    None,
}

# Use Option instead of null checks
frame findIndex(arr: *int, len: int, target: int) ret Maybe<int> {
    loop (local i: int = 0; i < len; i = i + 1) {
        if (*(arr + i) == target) {
            return Maybe.Some(i);
        }
    }
    return Maybe.None;
}

# Safe division
frame divide(a: int, b: int) ret Maybe<int> {
    if (b == 0) {
        return Maybe.None;
    }
    return Maybe.Some(a / b);
}

# Helper to unwrap with default
frame unwrapOr(opt: Maybe<int>, defaultVal: int) ret int {
    match (opt) {
        Maybe.Some(v) => { return v; },
        Maybe.None => { return defaultVal; },
    }
}

frame main() ret int {
    local nums: int[5] = [10, 20, 30, 40, 50];

    # Find existing element
    IO.print("Find 30: ");
    match (findIndex(&nums[0], 5, 30)) {
        Maybe.Some(idx) => {
            IO.print("Found at index ");
            IO.printInt(idx);
        },
        Maybe.None => {
            IO.print("Not found");
        },
    }
    IO.print("\n");

    # Find missing element
    IO.print("Find 99: ");
    match (findIndex(&nums[0], 5, 99)) {
        Maybe.Some(idx) => {
            IO.print("Found at index ");
            IO.printInt(idx);
        },
        Maybe.None => {
            IO.print("Not found");
        },
    }
    IO.print("\n");

    # Using unwrapOr
    local result: int = unwrapOr(divide(10, 3), -1);
    IO.print("\n10/3 = ");
    IO.printInt(result);
    IO.print("\n");

    local failed: int = unwrapOr(divide(10, 0), -1);
    IO.print("10/0 = ");
    IO.printInt(failed);
    IO.print(" (default)\n");

    return 0;
}

import [IO] from "std/io.bpl";

# Outcome<T, E> for operations that can fail
enum Outcome<T, E> {
    Ok(T),
    Err(E),
}

struct ParseError {
    message: string,
    position: int,
}

# Parse a single digit character
frame parseDigit(c: char) ret Outcome<int, ParseError> {
    if (c < '0' || c > '9') {
        return Outcome.Err(ParseError {
            message: "Not a digit",
            position: 0
        });
    }
    return Outcome.Ok(cast<int>(c) - cast<int>('0'));
}

# Check if Result is Ok
frame isOk<T, E>(r: Outcome<T, E>) ret bool {
    match (r) {
        Outcome.Ok(_) => { return true; },
        Outcome.Err(_) => { return false; },
    }
}

frame main() ret int {
    IO.print("=== Result Pattern ===\n\n");

    # Parse valid digit
    IO.print("Parse '7': ");
    match (parseDigit('7')) {
        Outcome.Ok(n) => {
            IO.print("Success: ");
            IO.printInt(n);
        },
        Outcome.Err(e) => {
            IO.print("Error: ");
            IO.print(e.message);
        },
    }
    IO.print("\n");

    # Parse invalid character
    IO.print("Parse 'x': ");
    match (parseDigit('x')) {
        Outcome.Ok(n) => {
            IO.print("Success: ");
            IO.printInt(n);
        },
        Outcome.Err(e) => {
            IO.print("Error: ");
            IO.print(e.message);
        },
    }
    IO.print("\n");

    return 0;
}

import [IO] from "std/io.bpl";

# Simple iterator over an array
struct IntIterator {
    data: *int,
    len: int,
    index: int,

    frame create(arr: *int, len: int) ret IntIterator {
        return IntIterator {
            data: arr,
            len: len,
            index: 0
        };
    }

    frame hasNext(this: *IntIterator) ret bool {
        return this.index < this.len;
    }

    frame next(this: *IntIterator) ret int {
        local value: int = *(this.data + this.index);
        this.index = this.index + 1;
        return value;
    }

    frame reset(this: *IntIterator) {
        this.index = 0;
    }
}

# Higher-order function using iterator
frame forEach(iter: *IntIterator, action: Lambda<void>(int)) {
    iter.reset();
    loop (iter.hasNext()) {
        action(iter.next());
    }
}

frame sumAll(iter: *IntIterator) ret int {
    iter.reset();
    local total: int = 0;
    loop (iter.hasNext()) {
        total = total + iter.next();
    }
    return total;
}

frame main() ret int {
    local data: int[5] = [1, 2, 3, 4, 5];
    local iter: IntIterator = IntIterator.create(&data[0], 5);

    IO.print("Using iterator:\n");

    # Manual iteration
    IO.print("Elements: ");
    loop (iter.hasNext()) {
        IO.printInt(iter.next());
        IO.print(" ");
    }
    IO.print("\n");

    # Using forEach
    IO.print("Squared: ");
    forEach(&iter, |x: int| {
        IO.printInt(x * x);
        IO.print(" ");
    });
    IO.print("\n");

    # Using sumAll
    IO.print("Sum: ");
    IO.printInt(sumAll(&iter));
    IO.print("\n");

    return 0;
}

import [IO] from "std/io.bpl";
extern malloc(size: int) ret *void;
extern free(ptr: *void);

# RAII: Resource Acquisition Is Initialization
# Resource management tied to object lifetime

struct ManagedBuffer {
    data: *int,
    size: int,

    # Acquire resource in constructor
    frame create(size: int) ret ManagedBuffer {
        IO.print("  [Allocating buffer]\n");
        return ManagedBuffer {
            data: cast<*int>(malloc(size * sizeof<int>())),
            size: size
        };
    }

    # Release resource in destructor
    frame destroy(this: *ManagedBuffer) {
        IO.print("  [Freeing buffer]\n");
        if (this.data != nullptr) {
            free(cast<*void>(this.data));
            this.data = nullptr;
        }
    }

    frame fill(this: *ManagedBuffer, value: int) {
        loop (local i: int = 0; i < this.size; i = i + 1) {
            *(this.data + i) = value;
        }
    }

    frame get(this: *ManagedBuffer, index: int) ret int {
        return *(this.data + index);
    }
}

frame useBuffer() {
    IO.print("Entering useBuffer()\n");

    local buf: ManagedBuffer = ManagedBuffer.create(5);
    defer { buf.destroy(); }  # Cleanup guaranteed!

    buf.fill(42);
    IO.print("Buffer[0] = ");
    IO.printInt(buf.get(0));
    IO.print("\n");

    IO.print("Exiting useBuffer()\n");
    # defer runs here automatically
}

frame main() ret int {
    IO.print("=== RAII Pattern ===\n\n");

    useBuffer();

    IO.print("\nBack in main()\n");

    return 0;
}

