import [IO] from "std/io.bpl";
extern malloc(size: int) ret *void;
extern free(ptr: *void);

enum Maybe<T> { Some(T), None }
enum Outcome<T, E> { Ok(T), Err(E) }

struct IntStack {
    data: *int,
    top: int,
    cap: int,

    frame create(capacity: int) ret IntStack {
        return IntStack {
            data: cast<*int>(malloc(capacity * sizeof<int>())),
            top: 0,
            cap: capacity
        };
    }

    frame destroy(this: *IntStack) {
        free(cast<*void>(this.data));
    }

    frame push(this: *IntStack, val: int) ret Outcome<bool, string> {
        if (this.top >= this.cap) {
            return Outcome.Err("Stack full");
        }
        *(this.data + this.top) = val;
        this.top = this.top + 1;
        return Outcome.Ok(true);
    }

    frame pop(this: *IntStack) ret Maybe<int> {
        if (this.top <= 0) {
            return Maybe.None;
        }
        this.top = this.top - 1;
        return Maybe.Some(*(this.data + this.top));
    }
}

frame main() ret int {
    local stack: IntStack = IntStack.create(3);
    defer { stack.destroy(); }

    # Push until full
    stack.push(10);
    stack.push(20);
    stack.push(30);

    # Try to push to full stack
    match (stack.push(40)) {
        Outcome.Ok(_) => { IO.print("Pushed 40\n"); },
        Outcome.Err(e) => {
            IO.print("Push failed: ");
            IO.print(e);
            IO.print("\n");
        },
    }

    # Pop all
    IO.print("Popping: ");
    loop {
        match (stack.pop()) {
            Maybe.Some(v) => {
                IO.printInt(v);
                IO.print(" ");
            },
            Maybe.None => { break; },
        }
    }
    IO.print("\n");

    return 0;
}
